"""Programmatic writing of reports/results.md.

results.md is never edited by hand. Each phase owns one section delimited by
HTML comment markers and replaces only that section, so phases can be re-run
independently without clobbering each other's results.
"""

from __future__ import annotations

import datetime as dt
from pathlib import Path
from typing import Any

RESULTS_HEADER = (
    "# ChurnLens results\n\n"
    "_Generated by code; every number below comes from an executed run. Do not edit by hand._\n"
)


def _markers(key: str) -> tuple[str, str]:
    return f"<!-- BEGIN:{key} -->", f"<!-- END:{key} -->"


def write_section(path: Path, key: str, body: str, header: str = RESULTS_HEADER) -> None:
    """Insert or replace the `key` section of a generated markdown file.

    `header` is used only when the file does not exist yet.
    """
    begin, end = _markers(key)
    block = f"{begin}\n{body.rstrip()}\n{end}"
    text = path.read_text(encoding="utf-8") if path.exists() else header
    if begin in text and end in text:
        head, rest = text.split(begin, 1)
        _, tail = rest.split(end, 1)
        text = f"{head}{block}{tail}"
    else:
        text = f"{text.rstrip()}\n\n{block}\n"
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(text, encoding="utf-8")


def run_banner(data_cfg: dict[str, Any]) -> str:
    """One line stating the data mode and sample every result came from."""
    pct = 100 if data_cfg["mode"] == "full" else data_cfg["user_sample_pct"]
    return (f"_Data: mode **{data_cfg['mode']}**, user sample **{pct}%** "
            f"(seed {data_cfg['sample_seed']}), log window {data_cfg['log_window_start']} to "
            f"{data_cfg['log_window_end']}. Generated {dt.datetime.now():%Y-%m-%d %H:%M}._")


def md_table(headers: list[str], rows: list[list[Any]], align: str | None = None) -> str:
    """Render a markdown table. `align` is a string of 'l'/'r' per column (default: left)."""
    align = align or "l" * len(headers)
    sep = ["---:" if a == "r" else "---" for a in align]
    lines = ["| " + " | ".join(headers) + " |", "|" + "|".join(sep) + "|"]
    lines += ["| " + " | ".join(str(c) for c in row) + " |" for row in rows]
    return "\n".join(lines)


def fmt_int(n: int | None) -> str:
    """Thousands-separated integer, or an em dash for None."""
    return "—" if n is None else f"{n:,}"


def fmt_pct(num: int, den: int, digits: int = 2) -> str:
    """Percentage string, safe for a zero denominator."""
    return "—" if not den else f"{100 * num / den:.{digits}f}%"
